-- Test fixture mirrors db/schema.ts. Production migrations are generated by Drizzle.
CREATE TABLE products(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,draft TEXT NOT NULL,published TEXT,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE settings(id TEXT PRIMARY KEY,value TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE history(id TEXT PRIMARY KEY,product_id TEXT NOT NULL,page_id TEXT NOT NULL,page TEXT NOT NULL,created TEXT NOT NULL,reason TEXT NOT NULL);
CREATE INDEX history_product_page ON history(product_id,page_id);
CREATE TABLE media(id TEXT PRIMARY KEY,product_id TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,created TEXT NOT NULL);
CREATE INDEX media_product ON media(product_id);
CREATE TABLE sessions(token TEXT PRIMARY KEY,expires INTEGER NOT NULL);
CREATE TABLE attempts(ip TEXT PRIMARY KEY,count INTEGER NOT NULL,reset INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS versions (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, label TEXT NOT NULL, slug TEXT NOT NULL, snapshot TEXT NOT NULL, created TEXT NOT NULL, UNIQUE(product_id,slug));
CREATE TABLE IF NOT EXISTS feedback (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, page_id TEXT NOT NULL, version TEXT NOT NULL DEFAULT '', helpful INTEGER NOT NULL CHECK(helpful IN (0,1)), comment TEXT NOT NULL DEFAULT '', visitor TEXT NOT NULL, created TEXT NOT NULL, UNIQUE(product_id,page_id,version,visitor));
CREATE INDEX IF NOT EXISTS feedback_product ON feedback(product_id,created);
CREATE TABLE IF NOT EXISTS feedback_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset INTEGER NOT NULL);
